contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tries to call c.sendTo(receiver, amount) with Ether pre-funded into c by sending
    // Ether to c from this contract prior to the call. We observe balances and whether the call reverts.
    function run(address payable receiver, uint amount, uint fund) public payable {
        require(address(this).balance >= fund);
        // fund the contract C by sending Ether from this contract
        if (fund > 0) {
            // send Ether to C
            (bool sent,) = address(c).call{value: fund}("");
            // funding may succeed or fail depending on C's fallback, but we allow both cases.
            // proceed regardless; observe balances below.
            sent; // silence unused warning
        }

        uint beforeC = address(c).balance;
        uint beforeReceiver = receiver == address(0) ? 0 : receiver.balance;

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterReceiver = receiver == address(0) ? 0 : receiver.balance;

        // General rule:
        // - If call reverted, balances unchanged: afterC == beforeC and afterReceiver == beforeReceiver.
        // - If call succeeded, then amount > 0, receiver != address(0), and afterC + amount == beforeC,
        //   and afterReceiver == beforeReceiver + amount.
        assert(
            reverted
            ? (afterC == beforeC && afterReceiver == beforeReceiver)
            : (amount > 0 && receiver != address(0) && afterC + amount == beforeC && afterReceiver == beforeReceiver + amount)
        );
    }

    receive() external payable {}
}

