        // If it reverted then neither balance change condition is required. This asserts the general correctness
        // of a successful owner-invoked transfer.
        assert(reverted || (beforeC >= afterC && beforeC - afterC == amount && afterR - beforeR == amount));
    }

    receive() external payable { }
