        require(receiver != address(0));
        // ensure this test contract has enough Ether to fund c if needed
        // The checker deploys a fresh c whose constructor sets owner to this contract
        // so this contract is the owner of c and can call sendTo.
        require(address(this).balance >= 0);

        // fund c with some Ether so it can send if amount > 0
        if (msg.value > 0) {
